#!/usr/bin/env node
// Side-by-side comparison harness for the sports artwork audit.
//
// Loads the canonical reference SVGs already generated by the Python
// templates at C:/Users/kepne/projects/L - PVTKRRX/PCnestspeaker/python-templates/<family>/out
// and renders the equivalent PVTKRRX SVG via renderSportsPosterTemplateSvg
// for the same matchup data. Both SVGs are rasterised to 600×900 PNG via
// sharp, then composited into one 1200×900 PNG with the canonical on the LEFT
// and PVTKRRX on the RIGHT, with a 4-pixel red divider band so the boundary
// is visible.
//
// Output:
//   .claude/proofs/sports-artwork/audit-template-vs-original/
//     <template>/
//       <sport>-canonical.png
//       <sport>-pvtkrrx.png
//       <sport>-side-by-side.png
//
// Usage:
//   node scripts/audit-template-vs-original.js               # all templates × sports
//   node scripts/audit-template-vs-original.js --template ticket-stub
//   node scripts/audit-template-vs-original.js --sport nba

