const TEMPLATE_FAMILIES = [
  { id: 'editorial', folder: '01-editorial', filePrefix: 'editorial' },
  { id: 'broadcast', folder: '02-broadcast', filePrefix: 'broadcast' },
  { id: 'sportsbook', folder: '03-sportsbook', filePrefix: 'sportsbook' },
  { id: 'trading-card', folder: '04-trading-card', filePrefix: 'trading-card' },
  { id: 'brutalist', folder: '05-brutalist', filePrefix: 'brutalist' },
  { id: 'ticket-stub', folder: '06-ticket-stub', filePrefix: 'ticket-stub' }
]

const W = 600
const H = 900
const DIVIDER = 4
const COMPOSITE_W = W * 2 + DIVIDER
const COMPOSITE_H = H

// Strip CSS `@import` lines (Google Fonts) — they contain literal `&`
// inside `url('...')` which sharp's strict XML parser rejects as bad
// entity refs. Sharp cannot fetch external fonts at rasterisation time
// anyway, so removing these lines does not change visual output beyond
// font fallback.
function stripExternalFontImports(svg) {
  // Google Fonts @import URLs contain `;` inside the query string
  // (`...wght@400;700&family=...`), so we must match the literal
  // `url('...');` shape, not stop at the first `;`. We also escape any
  // remaining bare `&` inside <style> blocks defensively (CSS attribute
  // selectors / nth-child don't use `&` so this is safe).
  return String(svg || '')
    .replace(/@import\s+url\([^)]*\)\s*;?/g, '')
    .replace(/<style>([\s\S]*?)<\/style>/g, (match, body) => {
      const cleaned = body.replace(/&(?![a-zA-Z#]+;)/g, '&amp;')
      if (!cleaned.trim()) return ''
      return `<style>${cleaned}</style>`
    })
}

async function rasterise(svg, label) {
  const safeSvg = stripExternalFontImports(svg)
  try {
    return await sharp(Buffer.from(safeSvg), { density: 192 })
      .resize({ width: W, height: H, fit: 'cover', position: 'centre' })
      .png({ compressionLevel: 9 })
      .toBuffer()
  } catch (error) {
    return await sharp({
      create: {
        width: W,
        height: H,
        channels: 3,
        background: { r: 16, g: 16, b: 20 }
      }
    })
      .composite([{
        input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
          <rect width="100%" height="100%" fill="#101014"/>
          <text x="50%" y="50%" font-family="Arial" font-size="32" fill="#ff5050" text-anchor="middle" dominant-baseline="middle">RENDER FAILED: ${label}</text>
          <text x="50%" y="58%" font-family="Arial" font-size="18" fill="#ff8080" text-anchor="middle" dominant-baseline="middle">${String(error.message || error).slice(0, 80)}</text>
        </svg>`),
        top: 0,
        left: 0
      }])
      .png()
      .toBuffer()
  }
}

async function composite(canonicalPng, pvtkrrxPng) {
  return await sharp({
    create: {
      width: COMPOSITE_W,
      height: COMPOSITE_H,
      channels: 3,
      background: { r: 200, g: 0, b: 0 }
    }
  })
    .composite([
      { input: canonicalPng, top: 0, left: 0 },
      { input: pvtkrrxPng, top: 0, left: W + DIVIDER }
    ])
    .png({ compressionLevel: 9 })
    .toBuffer()
}

function findCanonicalFile(family, sportEntry) {
  const dir = path.join(REFERENCE_ROOT, family.folder)
  if (!fs.existsSync(dir)) return null
  const expected = `${family.filePrefix}-${sportEntry.canonicalSlug}.svg`
  const direct = path.join(dir, expected)
  if (fs.existsSync(direct)) return direct
  // Fallback: glob for the family + sport short
  const candidates = fs.readdirSync(dir).filter((name) => name.endsWith('.svg'))
  return candidates.length > 0 ? path.join(dir, candidates[0]) : null
}

async function processCell(family, sport, sportEntry) {
  const cellOut = path.join(OUT_ROOT, family.id)
  fs.mkdirSync(cellOut, { recursive: true })

  const canonicalPath = findCanonicalFile(family, sportEntry)
  let canonicalPng
  if (canonicalPath && fs.existsSync(canonicalPath)) {
    const svg = fs.readFileSync(canonicalPath, 'utf8')
    canonicalPng = await rasterise(svg, `canonical/${family.id}/${sport}`)
    fs.writeFileSync(path.join(cellOut, `${sport}-canonical.png`), canonicalPng)
  } else {
    canonicalPng = await rasterise(
      `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><rect width="100%" height="100%" fill="#202024"/><text x="50%" y="50%" font-family="Arial" font-size="32" fill="#aaa" text-anchor="middle" dominant-baseline="middle">NO CANONICAL FILE</text></svg>`,
      `canonical/${family.id}/${sport}`
    )
  }

  let pvtkrrxSvg
  let pvtkrrxNote = ''
  try {
    const artwork = renderSportsPosterTemplateSvg({
      event: sportEntry,
      variant: 'poster',
      template: family.id
    })
    pvtkrrxSvg = artwork.svg
    pvtkrrxNote = `template=${artwork.template}, layoutFamily=${artwork.layoutFamily}`
  } catch (error) {
    pvtkrrxSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><rect width="100%" height="100%" fill="#400000"/><text x="50%" y="50%" font-family="Arial" font-size="24" fill="#fff" text-anchor="middle">PVTKRRX render failed: ${String(error.message || error)}</text></svg>`
    pvtkrrxNote = `error: ${error.message || error}`
  }
  const pvtkrrxPng = await rasterise(pvtkrrxSvg, `pvtkrrx/${family.id}/${sport}`)
  fs.writeFileSync(path.join(cellOut, `${sport}-pvtkrrx.svg`), pvtkrrxSvg)
  fs.writeFileSync(path.join(cellOut, `${sport}-pvtkrrx.png`), pvtkrrxPng)

  const compositePng = await composite(canonicalPng, pvtkrrxPng)
  fs.writeFileSync(path.join(cellOut, `${sport}-side-by-side.png`), compositePng)

  return {
    template: family.id,
    sport,
    canonicalPath,
    pvtkrrxNote,
    sideBySidePath: path.relative(REPO_ROOT, path.join(cellOut, `${sport}-side-by-side.png`)).replace(/\\/g, '/')
  }
}

async function main() {
  fs.mkdirSync(OUT_ROOT, { recursive: true })
  const wantTemplate = (process.argv.find((arg) => arg.startsWith('--template=')) || '').split('=')[1] ||
    (process.argv.includes('--template') ? process.argv[process.argv.indexOf('--template') + 1] : '')
  const wantSport = (process.argv.find((arg) => arg.startsWith('--sport=')) || '').split('=')[1] ||
    (process.argv.includes('--sport') ? process.argv[process.argv.indexOf('--sport') + 1] : '')

  const families = wantTemplate ? TEMPLATE_FAMILIES.filter((f) => f.id === wantTemplate) : TEMPLATE_FAMILIES
  const sports = wantSport ? Object.keys(MATCHUPS).filter((s) => s === wantSport) : Object.keys(MATCHUPS)

  const results = []
  for (const family of families) {
    for (const sport of sports) {
      const entry = MATCHUPS[sport]
      const cell = await processCell(family, sport, entry)
      results.push(cell)
      console.log(`${family.id}/${sport}: ${cell.sideBySidePath}  (${cell.pvtkrrxNote})`)
    }
  }

  fs.writeFileSync(
    path.join(OUT_ROOT, 'index.json'),
    JSON.stringify({ generatedAt: new Date().toISOString(), results }, null, 2),
    'utf8'
  )
  console.log(`\n${results.length} comparisons written to ${path.relative(REPO_ROOT, OUT_ROOT).replace(/\\/g, '/')}/`)
}

main().catch((error) => {
  console.error(error)
  process.exit(1)
})
